<script type="text/javascript">
	
	// var testdiv = document.getElementsById("page1-div");

	function savePDF()
	{
		var imgData;
		var imgData1='data:image/png;base64,';

		html2canvas($('#page1-div'),{
			useCORS:true,
			onrendered:function(canvas)
			{
				imgData = canvas.toDataURL('image/png');
				var doc = new jsPDF('p','pt','a4');

				doc.addImage(imgData,'PNG',15,15)
				
				// window.open(imgData);
				doc.addPage()
				doc.addImage(imgData1,'PNG',15,15,600,780)
				doc.save('samefile.pdf');

				var passport = $('#cand_passport').text();
				var cert_name = $('#cand_course').text();

                // alert(passport);

				var blob = doc.output('blob');

				var formData = new FormData();
				formData.append('pdf', blob);
				formData.append('passport',passport);
				formData.append('cert_name',cert_name);


				// $.ajax('/upload.php',

				// method: 'POST',
				// data: formData,
				// processData: false,
				// contentType: false,
				// success: function(data)console.log(data),
				// error: function(data)console.log(data)
				// );

				$.ajax({
              method: "POST",
              url: "upload.php",
              data: formData, // serializes the form's elements.
              processData: false,
			  contentType: false,
             success: function(data){
              alert(data);
              if($.trim(data)=="success")
              {
              	alert("certificate generated successfully");

              	// window.location.href="https://localhost/mass/admin/index.php/Certification";
              }
              else
              {
              	alert("something went wrong");
              }
               

            }
        });
			}
		});
	}
</script>

</head>

